package android.content;import android.database.ContentObserver;import android.net.Uri;import java.util.ArrayList;import java.util.List;import dev.mixer.android.OwnerHostProbe;
public class ContentResolver {public float animatorDurationScale=1;public final List<ContentObserver> observers=new ArrayList<>();public int addCalls,removeCalls;public void registerContentObserver(Uri uri,boolean descendants,ContentObserver observer){OwnerHostProbe.hit("ContentResolver.registerContentObserver","entry",this);addCalls++;observers.add(observer);OwnerHostProbe.hit("ContentResolver.registerContentObserver","beforeReturn",this);}public void unregisterContentObserver(ContentObserver observer){OwnerHostProbe.hit("ContentResolver.unregisterContentObserver","entry",this);removeCalls++;observers.removeIf(item->item==observer);OwnerHostProbe.hit("ContentResolver.unregisterContentObserver","beforeReturn",this);}public void hostNotify(){for(ContentObserver observer:List.copyOf(observers))observer.onChange(false);}}
